pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Admissible: amount > 0 and <= max address balance
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2); // keep it wide

        // Deploy a re-entrant attacker that calls withdrawAll again on receive
        ReEntrantAttacker attacker = new ReEntrantAttacker();

        // Fund the attacker
        vm.deal(address(attacker), amount);

        // Make the attacker the owner of c by deploying c from attacker's address
        // But we already deployed c in setUp with msg.sender = this test contract.
        // We need c to be owned by the attacker so that it can call withdrawAll.
        // Transfer ownership: prank current owner, call a function? No direct owner change.
        // But the fuzz test cannot change owner. The attacker must be the owner.
        // We must deploy a new C with the attacker as owner.
        // Re-deploy c? The setUp already deploys one, but we can deploy another inside the test
        // and use it. That is allowed as long as we keep the same C code.
        C reentrantC = new C(); // This C is owned by this test contract, not attacker.
        // To make attacker the owner, we can use vm.prank to deploy from the attacker.
        // Let's use vm.prank with attacker and deploy a new C.
        vm.prank(address(attacker));
        C c2 = C(address(new C())); // Now c2's owner is attacker.
        // We will use c2 instead of c for the test, but the assert must be on c?
        // The problem statement says "c" is deployed in setUp, but we can also test another instance.
        // To follow the rules, we can only observe c from setUp. However, the ADVERSARIAL COUNTERPARTY
        // deployment is allowed after setUp. We need the adversary to be the owner.
        // Since we cannot change c's owner, we must set it up so c is owned by the adversary from the start.
        // Alternative: we can deploy c in setUp with the attacker as owner using vm.prank.
    }
}

contract ReEntrantAttacker {
    bool private reentered;
    C public c;

    function setC(C _c) external {
        c = _c;
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
            reentered = false;
        }
    }
}

