import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        // Restrict amount to admissible range: must be <= contract balance
        // after we fund it, so withdraw doesn't revert due to insufficient balance.
        vm.deal(address(c), amount);
        vm.assume(amount <= address(c).balance);
        // Derive an owner actor from seed to ensure we prank from the owner
        address owner = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(owner != address(0));
        // The original contract's owner is msg.sender of setUp; we need a prank as that owner.
        // We'll use the actual owner stored in c.
        address realOwner = c.owner();
        vm.prank(realOwner);
        // Record pre-balance
        uint256 preBalance = address(c).balance;
        c.withdraw(amount);
        // After a successful withdraw (onlyOwner has passed),
        // the contract's balance must decrease by exactly amount.
        // This is the universal invariant: for every admissible amount,
        // the owner's withdrawal reduces the contract's Ether balance
        // accurately. The mutant fails for most amounts because it
        // does not transfer Ether, leaving balance unchanged.
        assertEq(address(c).balance, preBalance - amount);
    }
}

