        // Record owner before the call
        address ownerBefore = c.owner();
        // Fund caller with some Ether if needed (not strictly necessary for sendMoney, but for completeness)
        vm.deal(caller, amount);
        vm.prank(caller);
        try c.sendMoney(target, amount) {} catch {}
        // Owner should remain unchanged after a non-owner call
        address ownerAfter = c.owner();
        assertTrue(ownerBefore == ownerAfter);
    }
}
